    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '201: Which of the following is a "multifactorial" condition (result of many genes and environmental factors)?', '["Trisomy 21", "Cleft lip and palate", "PKU", "Turner Syndrome"]', 1, 'Most isolated structural defects like cleft lip, clubfoot, and neural tube defects are multifactorial.'),
    (v_topic_id, '202: What is the "recurrence risk" for parents who have one child with an isolated, multifactorial defect like spina bifida?', '["1%", "3-5%", "25%", "50%"]', 1, 'The risk increases with the number of affected family members but is generally low.'),
    (v_topic_id, '203: "Consanguinity" (reproduction between close relatives) increases the risk for which type of genetic disorders?', '["Autosomal Dominant", "Autosomal Recessive", "X-linked", "Chromosomal"]', 1, 'Increases the probability that both parents carry the same rare recessive allele.'),
    (v_topic_id, '204: A "malformation" is a primary defect in morphogenesis. What is a "deformation"?', '["A defect caused by mechanical force (e.g., uterine crowding)", "A defect caused by a metabolic toxin", "Failure of an organ to form", "A chromosomal deletion"]', 0, 'Deformations (like clubfoot or Potter sequence) occur when an intrinsically normal part is physically squeezed.'),
    (v_topic_id, '205: A "disruption" is a defect caused by the breakdown of a previously normal tissue. Which is a classic example?', '["Amniotic band sequence", "Trisomy 18", "Cleft palate", "Polydactyly"]', 0, 'Disruptions involve extrinsic factors that destroy or interfere with development.'),
    (v_topic_id, '206: "Anticipation" in genetics refers to:', '["Waiting for a diagnosis", "Increased severity or earlier onset of a disease in successive generations", "Expecting a mutation to occur", "None"]', 1, 'Classically seen in trinucleotide repeat disorders like Fragile X or Myotonic Dystrophy.'),
    (v_topic_id, '207: Which prenatal screening test has the highest sensitivity for Trisomy 21?', '["First trimester screen", "Quad screen", "Cell-free DNA (NIPT)", "Level II ultrasound"]', 2, 'Non-Invasive Prenatal Testing (cfDNA) has >99% sensitivity for Down syndrome.'),
    (v_topic_id, '208: "Nuchal translucency" measurement on ultrasound is performed during which time frame?', '["10-14 weeks gestation", "18-20 weeks", "24-28 weeks", "3rd trimester"]', 0, 'An increased translucency is a marker for aneuploidy and heart defects.'),
    (v_topic_id, '209: A "Quad Screen" with low AFP, low estriol, and high hCG/inhibin-A is suggestive of:', '["Trisomy 18", "Trisomy 21", "Neural tube defect", "Normal pregnancy"]', 1, 'This pattern is classic for Down syndrome.'),
    (v_topic_id, '210: High maternal serum alpha-fetoprotein (MSAFP) is most strongly associated with:', '["Trisomy 21", "Neural tube defects or abdominal wall defects", "Trisomy 18", "Maternal smoking"]', 1, 'Leakage of fetal protein occurs in "open" defects.'),
    (v_topic_id, '211: "Chorionic Villus Sampling (CVS)" is usually performed between:', '["8-10 weeks", "10-13 weeks", "15-20 weeks", "Any time after 20 weeks"]', 1, 'Allows for earlier diagnosis than amniocentesis but cannot test for AFP.'),
    (v_topic_id, '212: "Amniocentesis" is typically performed starting at what gestational age?', '["10 weeks", "15 weeks", "20 weeks", "25 weeks"]', 1, 'Used to obtain fetal cells for karyotype and measurement of AFP/AChE.'),
    (v_topic_id, '213: "Pleiotropy" refers to:', '["One gene causing multiple seemingly unrelated phenotypic effects", "Multiple genes causing one effect", "Environmental factors mimicking a gene", "None"]', 0, 'For example, the FBN1 mutation in Marfan affects the heart, eyes, and skeleton.'),
    (v_topic_id, '214: "Locus heterogeneity" means:', '["Mutations at different loci (genes) produce the same phenotype", "Different mutations in the same gene", "A gene that changes location", "None"]', 0, 'For example, many different genes can cause Osteogenesis Imperfecta.'),
    (v_topic_id, '215: "Variable expressivity" means:', '["The same genotype produces a different degree of severity in different people", "Some people with the gene have no symptoms", "A gene is only expressed in one organ", "None"]', 0, 'NF1 is a classic example: some have only café-au-lait spots, others have severe neurofibromas.'),
    (v_topic_id, '216: "Incomplete penetrance" occurs when:', '["Some individuals with a mutant genotype show no phenotype at all", "A gene is only partly inherited", "A child is a carrier only", "None"]', 0, 'For example, someone with a BRCA mutation may never develop cancer.'),
    (v_topic_id, '217: Which syndrome is associated with a "Gnas1" mutation and includes short stature, round face, and short 4th/5th metacarpals?', '["McCune-Albright", "Albright Hereditary Osteodystrophy (Pseudohypoparathyroidism)", "Prader-Willi", "Turner"]', 1, 'Involves resistance to PTH and other hormones.'),
    (v_topic_id, '218: "Imprinting" refers to:', '["The differential expression of a gene depending on which parent it was inherited from", "A baby learning to recognize its mother", "Chromosomal crossing over", "None"]', 0, 'Methylation silences genes from one parent.'),
    (v_topic_id, '219: A child has "cataracts" and "hypotonia" at birth, and the mother has difficulty releasing her grip after a handshake (myotonia). Diagnosis?', '["Congenital Myotonic Dystrophy", "Duchenne Muscular Dystrophy", "Spinal Muscular Atrophy", "Pompe Disease"]', 0, 'Autosomal dominant disorder showing marked anticipation.'),
    (v_topic_id, '220: What is the most common cause of "congenital adrenal hyperplasia"?', '["21-hydroxylase deficiency", "11-beta-hydroxylase deficiency", "17-alpha-hydroxylase deficiency", "3-beta-hydroxysteroid dehydrogenase deficiency"]', 0, 'Accounts for >90% of CAH cases.'),
    (v_topic_id, '221: "17-hydroxyprogesterone" levels are elevated in which condition?', '["PKU", "21-hydroxylase deficiency CAH", "Cushing Syndrome", "Addison Disease"]', 1, 'This is the primary screening marker for CAH in newborns.'),
    (v_topic_id, '222: Which maternal medication is associated with "fetal hydantoin syndrome"?', '["Valproate", "Phenytoin", "Carbamazepine", "Phenobarbital"]', 1, 'Symptoms include nail hypoplasia and cleft lip/palate.'),
    (v_topic_id, '223: Maternal smoking during pregnancy is most strongly associated with:', '["Limb reduction defects", "Intrauterine growth restriction (IUGR) and low birth weight", "Neural tube defects", "Macrocephaly"]', 1, 'Nicotine and carbon monoxide reduce oxygen delivery to the fetus.'),
    (v_topic_id, '224: "Fetal Cocaine Exposure" is primarily associated with:', '["Vascular disruptions (e.g., intestinal atresia, limb defects)", "Macroglossia", "Hirsutism", "Hypotonia"]', 0, 'Cocaine-induced vasoconstriction leads to ischemic events in the fetus.'),
    (v_topic_id, '225: A neonate with a "flat facial profile," "up-slanting palpebral fissures," and "small ears" most likely has:', '["Trisomy 21", "Trisomy 18", "Turner Syndrome", "Fetal Alcohol Syndrome"]', 0, 'These are common dysmorphic features of Down syndrome.'),
    (v_topic_id, '226: "Epicanthal folds" are a common feature of:', '["Down Syndrome", "Fetal Alcohol Syndrome", "Normal variation in some ethnicities", "All of the above"]', 3, 'Many dysmorphic features require evaluation in the context of the family.'),
    (v_topic_id, '227: Which of the following is an "X-linked recessive" disorder?', '["Cystic Fibrosis", "Duchenne Muscular Dystrophy", "Achondroplasia", "Sickle Cell Anemia"]', 1, 'Primarily affects males; mothers are carriers.'),
    (v_topic_id, '228: If a mother is a carrier for Duchenne Muscular Dystrophy, what is the risk for her "sons" to be affected?', '["25%", "50%", "75%", "100%"]', 1, 'Each son has a 50% chance of receiving the mutant X chromosome.'),
    (v_topic_id, '229: What is the inheritance of "Cystic Fibrosis"?', '["Autosomal Dominant", "Autosomal Recessive", "X-linked", "Mitochondrial"]', 1, 'Both parents must be carriers (25% recurrence risk).'),
    (v_topic_id, '230: "Dysmorphic" refers to:', '["An abnormality in the shape or structure of a body part", "A metabolic error", "Intellectual disability", "None"]', 0, 'Derived from the Greek for "bad form."'),
    (v_topic_id, '231: Which syndrome is characterized by "Greek warrior helmet" facies and a 4p- deletion?', '["Wolf-Hirschhorn Syndrome", "Cri-du-chat Syndrome", "DiGeorge Syndrome", "Williams Syndrome"]', 0, 'Features include prominent glabella and hypertelorism.'),
    (v_topic_id, '232: "Beckwith-Wiedemann Syndrome" involves an increased risk for which childhood malignancy?', '["Leukemia", "Wilms tumor", "Retinoblastoma", "Neuroblastoma"]', 1, 'Overgrowth syndromes are often linked to embryonal tumors.'),
    (v_topic_id, '233: A neonate has "polydactyly," "scalp defects," and "clenched fists." Which trisomy is most likely?', '["13", "18", "21", "None"]', 0, 'Scalp defects (aplasia cutis) and polydactyly are classic for Trisomy 13.'),
    (v_topic_id, '234: "Overlapping fingers" (2nd over 3rd, 5th over 4th) are classic for:', '["Trisomy 13", "Trisomy 18", "Trisomy 21", "Turner Syndrome"]', 1, 'A high-yield physical finding for Edwards syndrome.'),
    (v_topic_id, '235: A child has "hypoplasia of the thumb" and "recurrent infections" (Diamond-Blackfan anemia). This is a:', '["Marrow failure syndrome", "Structural defect only", "Metabolic disorder", "Teratogen effect"]', 0, 'DBA is a congenital pure red cell aplasia often associated with thumb anomalies.'),
    (v_topic_id, '236: "Radial dysplasia" is a common feature in which "association"?', '["VACTERL", "CHARGE", "MURCS", "PHACE"]', 0, 'Radial limb defects are the "L" in VACTERL.'),
    (v_topic_id, '237: A neonate has "macroglossia" (large tongue) and "hypoglycemia." Diagnosis?', '["Down Syndrome", "Beckwith-Wiedemann Syndrome", "Cretinism", "Noonan Syndrome"]', 1, 'Hyperinsulinism is a feature of BWS.'),
    (v_topic_id, '238: "Omphalocele" is a major feature of which syndrome?', '["Beckwith-Wiedemann Syndrome", "Trisomy 18", "Trisomy 13", "All of the above"]', 3, 'Unlike gastroschisis, omphalocele is frequently syndromic.'),
    (v_topic_id, '239: A child with "blue sclerae" but NO history of fractures may have:', '["Type 1 Osteogenesis Imperfecta", "Ehlers-Danlos Syndrome", "Normal variation in infants", "All of the above"]', 3, 'The sclera is thin in many conditions, allowing the choroid to show through.'),
    (v_topic_id, '240: "Aplasia cutis congenita" is most often found on the:', '["Scalp", "Back", "Abdomen", "Legs"]', 0, 'A localized absence of skin at birth.'),
    (v_topic_id, '241: A "simian crease" is found in about what percentage of the "normal" population?', '["0%", "5%", "25%", "50%"]', 1, 'It is common enough that it must be seen with other markers to suggest Down syndrome.'),
    (v_topic_id, '242: "Coloboma of the iris" is a defect in the closure of the:', '["Choroid fissure", "Lens placode", "Optic cup", "Neural tube"]', 0, 'Occurs during the 6th-7th week of development.'),
    (v_topic_id, '243: "Atresia choanae" is a major diagnostic criterion for:', '["CHARGE Syndrome", "VACTERL Association", "DiGeorge Syndrome", "Noonan Syndrome"]', 0, 'The "A" in CHARGE stands for Atresia of the choanae.'),
    (v_topic_id, '244: A neonate with "low-set, posteriorly rotated ears" and "micrognathia" likely has:', '["A chromosomal abnormality", "A normal variation", "Isolated ear infection", "None"]', 0, 'These are classic "minor" dysmorphic markers for aneuploidy.'),
    (v_topic_id, '245: "Pre-axial polydactyly" refers to an extra digit on the:', '["Thumb/Big toe side", "Pinky side", "Middle", "None"]', 0, 'Often associated with Fanconi anemia or Holt-Oram.'),
    (v_topic_id, '246: "Syndactyly" of the 2nd and 3rd toes is a common minor finding in:', '["Smith-Lemli-Opitz Syndrome", "Normal children", "Down Syndrome", "Both A and B"]', 3, 'It is highly suggestive of SLO but can be found in others.'),
    (v_topic_id, '247: "Phocomelia" is the hallmark of exposure to which teratogen?', '["Lithium", "Thalidomide", "Warfarin", "Alcohol"]', 1, 'Limbs are short and fin-like.'),
    (v_topic_id, '248: "Ebstein Anomaly" is the hallmark of exposure to which teratogen?', '["Alcohol", "Lithium", "Valproate", "Phenytoin"]', 1, 'Involves "atrialization" of the right ventricle.'),
    (v_topic_id, '249: "Nasal hypoplasia" is the hallmark of exposure to which teratogen?', '["Warfarin", "Isotretinoin", "Tetracycline", "Cocaine"]', 0, 'Also causes stippled epiphyses.'),
    (v_topic_id, '250: "Yellow-brown staining of the teeth" is caused by maternal use of:', '["Penicillin", "Tetracycline", "Erythromycin", "Aspirin"]', 1, 'Tetracyclines bind to calcium in developing teeth and bones.'),
    (v_topic_id, '251: Which infection causes "chorioretinitis, hydrocephalus, and intracranial calcifications"?', '["Rubella", "Toxoplasmosis", "CMV", "Syphilis"]', 1, 'The classic triad of congenital toxoplasmosis.'),
    (v_topic_id, '252: Which infection causes "periventricular calcifications" and microcephaly?', '["Toxoplasmosis", "CMV (Cytomegalovirus)", "Rubella", "HIV"]', 1, 'CMV is the most common congenital infection in the US.'),
    (v_topic_id, '253: A child with "sensorineural hearing loss" should be evaluated for which congenital infection?', '["CMV", "Rubella", "Syphilis", "All of the above"]', 3, 'Hearing loss is a common late-onset finding in TORCH infections.'),
    (v_topic_id, '254: "PKU" screening is done using blood from a:', '["Vein", "Heel prick", "Umbilical cord", "Artery"]', 1, 'Performed 24-48 hours after birth to ensure protein intake has occurred.'),
    (v_topic_id, '255: If a mother with PKU does NOT follow a low-phenylalanine diet during pregnancy, the baby will likely have:', '["PKU", "Microcephaly and intellectual disability (Maternal PKU Syndrome)", "Normal development", "Obesity"]', 1, 'High levels of phenylalanine cross the placenta and act as a teratogen.'),
    (v_topic_id, '256: "Classical Galactosemia" leads to an increased risk of neonatal death from:', '["Gram-positive sepsis", "E. coli sepsis", "Heart failure", "Renal failure"]', 1, 'Galactose inhibits the bactericidal activity of neutrophils against E. coli.'),
    (v_topic_id, '257: Which glycogen storage disease is also a "lysosomal storage disease"?', '["Type I", "Type II (Pompe)", "Type III", "Type IV"]', 1, 'Pompe disease involves acid alpha-glucosidase in the lysosome.'),
    (v_topic_id, '258: "Gaucher cells" (crinkled paper appearance) are found in the:', '["Brain", "Bone marrow", "Liver", "Lungs"]', 1, 'Lipid-laden macrophages are the hallmark of Gaucher disease.'),
    (v_topic_id, '259: Which mucopolysaccharidosis is "X-linked recessive"?', '["Hurler Syndrome", "Hunter Syndrome", "Sanfilippo Syndrome", "Morquio Syndrome"]', 1, 'Hunter (MPS II) lacks corneal clouding and is X-linked.'),
    (v_topic_id, '260: "Cornelia de Lange Syndrome" facial features include:', '["Synophrys (unibrow)", "Thin upper lip", "Long philtrum", "All of the above"]', 3, 'A distinct and recognizable facial phenotype.'),
    (v_topic_id, '261: "Achondroplasia" is caused by a mutation in:', '["FGFR3", "COL1A1", "FBN1", "PAX6"]', 0, 'Fibroblast Growth Factor Receptor 3.'),
    (v_topic_id, '262: "Thanatophoric dysplasia" is a severe, lethal skeletal dysplasia characterized by:', '["Extremely short limbs and ''telephone receiver'' femurs", "Blue sclerae", "Macroglossia", "Polydactyly"]', 0, 'Most common lethal skeletal dysplasia.'),
    (v_topic_id, '263: "Dandy-Walker" malformation always involves which part of the brain?', '["Cerebellar vermis", "Corpus callosum", "Thalamus", "Pituitary"]', 0, 'Agenesis or hypoplasia of the vermis.'),
    (v_topic_id, '264: "Holoprosencephaly" is often associated with "midline" facial defects such as:', '["Cyclopia (single eye) or cebocephaly (single nostril)", "Cleft lip/palate", "Hypertelorism", "Both A and B"]', 3, '"The face predicts the brain."'),
    (v_topic_id, '265: "Gastroschisis" is associated with "maternal" risk factors like:', '["Advanced maternal age", "Young maternal age (<20 years)", "Diabetes", "Obesity"]', 1, 'Incidence is increasing, particularly in babies of very young mothers.'),
    (v_topic_id, '266: Infants with "Gastroschisis" are at high risk for "short bowel syndrome" due to:', '["Intestinal atresia or volvulus", "Lack of colon", "Stomach malrotation", "None"]', 0, 'The exposed bowel is prone to injury and ischemia.'),
    (v_topic_id, '267: "Tracheoesophageal fistula" is part of which two major associations?', '["VACTERL and CHARGE", "Down and Turner", "NF1 and TSC", "None"]', 0, 'It is the "TE" in VACTERL and often seen in CHARGE.'),
    (v_topic_id, '268: "Duodenal atresia" is associated with which chromosomal abnormality in 30% of cases?', '["Trisomy 13", "Trisomy 18", "Trisomy 21", "Turner Syndrome"]', 2, 'Classic board association.'),
    (v_topic_id, '269: "Imperforate anus" should be evaluated with which imaging in the first 24 hours?', '["Invertogram or cross-table lateral X-ray", "CT", "MRI", "Ultrasound"]', 0, 'Used to determine the level of the lesion (high vs. low).'),
    (v_topic_id, '270: "Biliary atresia" presents with "conjugated" jaundice at what age?', '["Birth", "2-8 weeks of age", "6 months", "Puberty"]', 1, 'Requires the Kasai procedure for surgical drainage.'),
    (v_topic_id, '271: "Klippel-Feil Syndrome" is characterized by:', '["Congenital fusion of cervical vertebrae", "Limb overgrowth", "Port-wine stain", "Hearing loss"]', 0, 'Presents with a short neck, low hairline, and limited neck mobility.'),
    (v_topic_id, '272: "Radial aplasia" (absent radius) with "preserved" thumbs is classic for:', '["TAR Syndrome", "Holt-Oram Syndrome", "Fanconi Anemia", "VACTERL"]', 0, 'A very specific exam differentiator.'),
    (v_topic_id, '273: "Arthrogryposis Multiplex Congenita" refers to:', '["Multiple congenital joint contractures", "Multiple fractures", "Large muscles", "Bony overgrowth"]', 0, 'Often due to fetal akinesia (lack of movement in utero).'),
    (v_topic_id, '274: "Sirenomelia" is also known as:', '["Mermaid syndrome (fused legs)", "Short limb syndrome", "Large head syndrome", "None"]', 0, 'A severe form of caudal regression.'),
    (v_topic_id, '275: "Craniofacial microsomia" (Hemifacial microsomia) is the most common cause of:', '["Facial asymmetry", "Blindness", "Deafness", "Macroglossia"]', 0, 'The face on one side is underdeveloped.'),
    (v_topic_id, '276: "Waardenburg Syndrome" is a disorder of:', '["Neural crest cell migration", "Collagen synthesis", "Hormone production", "Amino acid metabolism"]', 0, 'Explains the combination of pigmentary and auditory defects.'),
    (v_topic_id, '277: "Stickler Syndrome" should be regularly monitored for:', '["Retinal detachment", "Heart failure", "Liver failure", "Seizures"]', 0, 'High myopia and vitreoretinal degeneration lead to detachment risk.'),
    (v_topic_id, '278: "Usher Syndrome" involves:', '["Congenital deafness and progressive vision loss (Retinitis Pigmentosa)", "Heart and lung defects", "Limb defects", "None"]', 0, 'A leading cause of combined deaf-blindness.'),
    (v_topic_id, '279: "Alport Syndrome" (collagen IV defect) involves:', '["Hereditary nephritis, hearing loss, and eye anomalies", "Bone fractures", "Skin hyperextensibility", "None"]', 0, 'Presents with hematuria in childhood.'),
    (v_topic_id, '280: "Noonan Syndrome" is associated with mutations in the "RAS/MAPK" pathway, also known as:', '["RASopathies", "G-protein disorders", "Mitochondrial disorders", "Storage diseases"]', 0, 'Includes Costello and CFC syndromes.'),
    (v_topic_id, '281: "Neurofibromatosis Type 1" has which inheritance pattern?', '["Autosomal Dominant", "Autosomal Recessive", "X-linked", "Mitochondrial"]', 0, '50% are inherited, 50% are new mutations.'),
    (v_topic_id, '282: "Tuberous Sclerosis" has which inheritance pattern?', '["Autosomal Dominant", "Autosomal Recessive", "X-linked", "Mitochondrial"]', 0, 'Mutations in TSC1 or TSC2.'),
    (v_topic_id, '283: "Sturge-Weber" is unique among phakomatoses because it is:', '["Not inherited (it is sporadic/mosaic)", "X-linked", "Autosomal recessive", "Lethal in utero"]', 0, 'Caused by a somatic mutation in the GNAQ gene.'),
    (v_topic_id, '284: "Von Hippel-Lindau" (VHL) syndrome includes:', '["Hemangioblastomas (CNS/Retina) and Renal Cell Carcinoma", "Café-au-lait spots", "Ash-leaf spots", "Port-wine stain"]', 0, 'Autosomal dominant tumor suppressor gene mutation.'),
    (v_topic_id, '285: "Marfan Syndrome" lens dislocation is:', '["Superior/Temporal (Upward)", "Inferior/Nasal (Downward)", "Fixed", "None"]', 0, 'Helps distinguish it from Homocystinuria (Downward).'),
    (v_topic_id, '286: "Ehlers-Danlos" Vascular Type (Type IV) is life-threatening due to risk of:', '["Arterial or organ rupture", "Heart block", "Kidney failure", "Blindness"]', 0, 'Caused by defects in Type III collagen.'),
    (v_topic_id, '287: "Mosaic Turner Syndrome" (e.g., 45,X/46,XX) may result in:', '["A milder phenotype and potentially preserved fertility", "More severe disease", "Lethality", "None"]', 0, 'Presence of a normal cell line can mitigate symptoms.'),
    (v_topic_id, '288: "47,XYY" Syndrome is often characterized by:', '["Tall stature and behavioral/learning difficulties", "Short stature", "Small testes", "Severe birth defects"]', 0, 'Most individuals are phenotypically normal and undiagnosed.'),
    (v_topic_id, '289: "47,XXX" (Trisomy X) in females is often:', '["Asymptomatic or associated with tall stature and learning disabilities", "Lethal", "Associated with primary amenorrhea", "None"]', 0, 'Similar to XYY, many go undiagnosed.'),
    (v_topic_id, '290: Final Pearl: In dysmorphology, the presence of 3 or more "minor" anomalies (like a single crease) increases the risk of a "major" anomaly to:', '["5%", "25%", "90%", "100%"]', 1, 'Minor anomalies serve as indicators for more significant underlying structural defects.');
